// KLGA (PLAN 1.6): LaGuardia imported as a format check, not playable. The base is generated by
// tools/import-airport.ts from OSM; the hand-curated parts are the agent's sourced picks, each
// cited in docs/airports/KLGA-notes.md.

import { describe, expect, it } from 'vitest';
import klgaBase from '../../data/airports/KLGA.json' with { type: 'json' };
import klgaOverrides from '../../data/airports/KLGA.overrides.json' with { type: 'json' };
import type { Taxi } from '../sim/commands.ts';
import { resolveRoute } from '../sim/route.ts';
import { parseTerse } from '../sim/terse.ts';
import { edgeLength, edgesAt, indexAirport, otherEnd } from './graph.ts';
import { loadAirport } from './load.ts';
import { validateAirport } from './validate.ts';

const KLGA = loadAirport(klgaBase, klgaOverrides);
const INDEX = indexAirport(KLGA);

/** The taxi instruction of a terse command written without its callsign. */
function taxiOf(text: string): Taxi {
  const parsed = parseTerse(`TST1 ${text}`);
  if (!parsed.ok) throw new Error(`'${text}' doesn't parse: ${parsed.error.message}`);
  const [instruction] = parsed.command.type === 'transmission' ? parsed.command.instructions : [];
  if (instruction?.type !== 'taxi') throw new Error(`'${text}' is not a taxi instruction`);
  return instruction;
}

/** The runway(s) whose centerline node `node` is. */
const runwaysAt = (node: string) => [...new Set(edgesAt(INDEX, node).filter((e) => e.kind === 'runway').map((e) => e.runway as string))].sort();

describe('KLGA', () => {
  it('validates with no errors; the only warnings are no pad and no penalty box (none sourced for LGA)', () => {
    const result = validateAirport(KLGA);
    expect(result.errors.map((e) => `${e.code}: ${e.message}`)).toEqual([]);
    expect(result.warnings.map((w) => w.code)).toEqual(['no-holding-pad', 'no-penalty-box']);
    expect(KLGA.source?.license).toContain('ODbL');
  });

  it('has runways 4/22 and 13/31 (7,002 ft each, Chart Supplement) with runway holds on the taxiways that meet them, and the ILS holds', () => {
    expect(KLGA.runways.map((r) => [r.id, r.ends[0].designator, r.ends[1].designator])).toEqual([['4/22', '4', '22'], ['13/31', '13', '31']]);
    for (const r of KLGA.runways) {
      const lengthM = KLGA.edges.filter((e) => e.runway === r.id).reduce((m, e) => m + edgeLength(INDEX, e), 0);
      expect(Math.abs(lengthM / 0.3048 / 7002 - 1), r.id).toBeLessThan(0.01);
    }
    // Taxiways meeting each runway on the FAA diagram (AL-289). C's entry onto 4/22 is guarded by
    // CY's hold 5 m before the C/CY junction (h9311515566), so C itself carries none.
    const expected: Record<string, string[]> = {
      '4/22': ['R', 'U', 'P', 'G', 'Q', 'F', 'E', 'D', 'CY', 'Y', 'YY', 'AA', 'B'],
      '13/31': ['P', 'AA', 'R', 'S', 'T', 'L', 'J', 'M', 'V', 'W', 'Z'],
    };
    for (const [runway, taxiways] of Object.entries(expected)) {
      for (const t of taxiways) {
        const holds = KLGA.holdShorts.filter((h) => h.kind === 'runway' && h.runways.includes(runway) && edgesAt(INDEX, h.node).some((e) => e.name === t));
        expect(holds.length, `${runway} on ${t}`).toBeGreaterThan(0);
      }
    }
    expect(KLGA.holdShorts.find((h) => h.id === 'h9311515566')?.runways).toEqual(['4/22']);
    // The chart's three ILS hold lines (R near the 22 end; B, and AA/AC, near the 4 end) are four
    // OSM nodes, all on 4/22's ILS. B's is the one Rwy 4 departures may be held at (chart note).
    expect(KLGA.holdShorts.filter((h) => h.kind === 'ils').map((h) => [h.id, h.runways, [...new Set(edgesAt(INDEX, h.node).map((e) => e.name))]])).toEqual([
      ['h3067763441', ['4/22'], ['B']],
      ['h9311515569', ['4/22'], ['AC']],
      ['h9311515570', ['4/22'], ['AA']],
      ['h9311571489', ['4/22'], ['R']],
    ]);
  });

  it("has terminals B and C (laguardiaairport.com), B's gates matched to its concourse buildings", () => {
    expect(KLGA.terminals.map((t) => t.id)).toEqual(['TB', 'TC']);
    // Terminal B is a headhouse plus the Eastern and Western Concourses (OSM names them only
    // "… Concourse"); the overrides assign those buildings to TB, so their stands are TB gates.
    const tb = KLGA.gates.filter((g) => g.terminal === 'TB').map((g) => g.name);
    for (const name of ['28', '30', '43', '55', '58']) expect(tb, name).toContain(name);
    expect(KLGA.areas.filter((a) => a.terminal === 'TB').map((a) => a.name).sort()).toEqual(
      ['Eastern Concourse', 'Terminal B', 'Terminal B East Pedestrian Bridge', 'Terminal B West Pedestrian Bridge', 'Western Concourse'],
    );
  });

  it('has the airlines per terminal (laguardiaairport.com) and one tower for both runways (Chart Supplement)', () => {
    expect(KLGA.terminals.map((t) => [t.id, t.airlines])).toEqual([
      ['TB', ['ACA', 'AAL', 'FFT', 'JBU', 'POE', 'SWA', 'UAL']],
      ['TC', ['DAL']],
    ]);
    expect(KLGA.towerPositions).toEqual([{ id: 'twr-118.7', name: 'LaGuardia Tower', frequency: '118.7' }]);
    expect(KLGA.runways.map((r) => [r.id, r.towerPosition])).toEqual([['4/22', 'twr-118.7'], ['13/31', 'twr-118.7']]);
  });

  it('starts in the FAA-profiled configuration, land 22 and depart 13, with arrival exits and a 13 departure line', () => {
    expect(KLGA.defaultConfiguration).toBe('22-13');
    expect(KLGA.configurations.map((c) => [c.id, c.runways.map((u) => [u.end, u.roles, u.arrivalExits?.map((id) => KLGA.runwayExits.find((x) => x.id === id)?.taxiway)])])).toEqual([
      ['22-13', [['22', ['arrivals'], ['E', 'C', 'Y', 'B']], ['13', ['departures'], undefined]]],
    ]);
    const [line, ...more] = KLGA.departureLines;
    expect(more).toEqual([]);
    expect(line && [line.runwayEnd, line.holdShort, line.exits.map((x) => x.taxiway)]).toEqual(['13', 'h9311536450', ['BB', 'G']]);
    expect(line?.edges.map((id) => INDEX.edges.get(id)?.name)).toEqual(['P', 'P', 'P', 'P', 'P', 'P']);
    const issues = validateAirport(KLGA);
    expect(issues.errors.filter((e) => e.code.startsWith('departure-line') || e.code.startsWith('configuration') || e.code.startsWith('runway-exit'))).toEqual([]);
    expect(issues.warnings.map((w) => w.code).filter((c) => c.startsWith('configuration') || c.includes('configuration'))).toEqual([]);
  });

  it('puts the ramp boundary at the mouths of the gate alleys: lanes 1–3 are ground taxiways, the alleys ramp lanes', () => {
    const kinds = (name: string) => [...new Set(KLGA.edges.filter((e) => e.name === name).map((e) => e.kind))];
    for (const lane of ['1', '2', '3']) expect(kinds(lane), `lane ${lane}`).toEqual(['taxiway']);
    // Each gate alley is the ramp's behind its check-in point; the short stub from A (or Z) to
    // that point stays ground's, named for the lane (the movement-area stub, as at JFK).
    for (const lane of ['5', '6', '7', '8', '9', '11', '12', '15', '16', '17', '18', '19']) expect(kinds(lane), `lane ${lane}`).toContain('rampLane');
    // Check-in names are the alley numbers (strings, like every name).
    expect([...new Set(KLGA.rampHandoffs.map((h) => h.name))].sort((p, q) => Number(p) - Number(q))).toEqual(['5', '6', '7', '8', '9', '11', '12', '15', '16', '17', '18', '19']);
    const ramp = validateAirport(KLGA).errors.concat(validateAirport(KLGA).warnings).filter((i) => i.code.startsWith('gate-') || i.code.startsWith('ramp-'));
    expect(ramp.map((i) => `${i.code}: ${i.message}`)).toEqual([]);
  });

  it('protects every way onto a runway, including both branches of a fork at a hold line', () => {
    // n46537587: D and an unnamed fillet onto 4/22 split exactly at the OSM hold node, so the
    // hold line guards both branches: one hold-short per branch.
    expect(KLGA.holdShorts.filter((h) => h.node === 'n46537587').map((h) => [h.id, h.runways, h.towardEdge])).toEqual([
      ['h46537587', ['4/22'], 'w5783993-n46537587-n6236284107'],
      ['h46537587.2', ['4/22'], 'w302528231-n46537587-n46535616'],
    ]);
    const codes = validateAirport(KLGA).errors.map((e) => e.code);
    expect(codes.filter((c) => c === 'runway-entry-unprotected' || c === 'disconnected-network')).toEqual([]);
  });

  it('resolves "taxi 13 via #1 #3 A G P" from check-in 9 to a connected path over numbered lanes 1 and 3, across 4/22, to the 13 line', () => {
    // A Terminal B departure out of alley 9, checking in where 9 meets lane 1 (rh9L1).
    const start = { node: 'n10561870574', arrivedVia: 'w1102689634-n8873178889-n10561870574', terminal: 'TB' };
    expect(INDEX.edges.get(start.arrivedVia)?.name).toBe('9');
    const result = resolveRoute(INDEX, taxiOf('taxi 13 via #1 #3 A G P'), start);
    if (result.type !== 'path') throw new Error(`expected a path, got ${JSON.stringify(result)}`);
    expect(result.nodes.length).toBe(result.edges.length + 1);
    result.edges.forEach((id, i) => {
      const edge = INDEX.edges.get(id);
      expect(edge?.kind, id).toBe('taxiway');
      expect([edge?.from, edge?.to].sort(), id).toEqual([result.nodes[i], result.nodes[i + 1]].sort());
    });
    const names = result.edges.map((id) => INDEX.edges.get(id)?.name ?? '-').filter((n, i, all) => n !== all[i - 1]);
    expect(names[0]).toBe('1');
    expect(names.filter((n) => n !== '-')).toEqual(['1', '3', 'A', 'G', 'P']);
    expect(result.destination).toEqual({ kind: 'runway', runwayEnd: '13', departureLine: 'line13', holdShort: 'h9311536450' });
    // It crosses 4/22 on G, past G's runway hold lines, facing the runway.
    expect(result.holdShorts.filter((h) => h.kind === 'runway').map((h) => [h.id, h.runways])).toEqual([
      ['h9311536442', ['4/22']],
      ['h9311536443', ['4/22']],
    ]);
  });

  it('represents the runway intersection (HS 1): its hold-shorts reference both runways', () => {
    // 4/22 and 13/31 cross at one shared node.
    const crossing = KLGA.nodes.filter((n) => runwaysAt(n.id).length === 2).map((n) => n.id);
    expect(crossing).toEqual(['n1168727438']);

    // AA runs into the intersection (FAA diagram AL-289, HS 1): past its hold line an aircraft
    // enters 13/31 32 m from 4/22's centerline, inside both runways' hold lines. So the hold
    // protects both runways.
    const aa = KLGA.holdShorts.find((h) => h.id === 'h3061622399');
    expect(aa && [aa.kind, aa.runways]).toEqual(['runway', ['13/31', '4/22']]);

    // The runway holding position markings on the runways themselves (OSM holding_position:type
    // =runway on each centerline, about 75 m either side of the crossing): each sits on one
    // runway and protects the other, facing along its runway toward the crossing node.
    const onRunway = KLGA.holdShorts.filter((h) => runwaysAt(h.node).length > 0);
    expect(onRunway.map((h) => [h.id, h.kind, runwaysAt(h.node), h.runways]).sort()).toEqual([
      ['h9311536458', 'runway', ['4/22'], ['13/31']],
      ['h9311536459', 'runway', ['4/22'], ['13/31']],
      ['h9311536460', 'runway', ['13/31'], ['4/22']],
      ['h9311536461', 'runway', ['13/31'], ['4/22']],
    ]);
    for (const h of onRunway) {
      // Walking along its own runway from the hold via towardEdge reaches the crossing.
      let node = h.node;
      let edge = INDEX.edges.get(h.towardEdge);
      const seen = new Set<string>();
      while (edge && node !== 'n1168727438' && !seen.has(edge.id)) {
        seen.add(edge.id);
        expect(edge.kind, h.id).toBe('runway');
        node = otherEnd(edge, node);
        const own = runwaysAt(h.node)[0];
        edge = edgesAt(INDEX, node).find((e) => e.kind === 'runway' && e.runway === own && !seen.has(e.id));
      }
      expect(node, `${h.id} faces the crossing`).toBe('n1168727438');
    }
  });
});
